import { test, expect } from '@playwright/test';

test.describe('User Profile Update', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should display confirmation message after updating profile', async ({ page }) => {
    await page.getByLabel('Name').fill('John Doe');
    await page.getByLabel('Email').fill('john.doe@example.com');
    await page.getByRole('button', { name: 'Update Profile' }).click();

    const confirmationMessage = await page.getByText('Profile updated successfully!');
    await expect(confirmationMessage).toBeVisible();
  });

  test('should not display confirmation message if update fails', async ({ page }) => {
    await page.getByLabel('Name').fill('');
    await page.getByRole('button', { name: 'Update Profile' }).click();

    const errorMessage = await page.getByText('Please fill out this field.');
    await expect(errorMessage).toBeVisible();
  });
});
